import{_ as r,o as e,c as t,a3 as o}from"./chunks/framework.Dj4Lt7vj.js";const f=JSON.parse('{"title":"遇到故障怎么反馈","description":"","frontmatter":{"title":"遇到故障怎么反馈"},"headers":[],"relativePath":"faq/report.md","filePath":"faq/report.md","lastUpdated":1787948622000}'),l={name:"faq/report.md"};function i(n,a,s,c,h,d){return e(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="遇到故障怎么反馈" tabindex="-1">遇到故障怎么反馈 <a class="header-anchor" href="#遇到故障怎么反馈" aria-label="Permalink to &quot;遇到故障怎么反馈&quot;">​</a></h1><p>软件出问题时怎么自查、怎么反馈能最快得到解决。</p><h2 id="先做三件事" tabindex="-1">先做三件事 <a class="header-anchor" href="#先做三件事" aria-label="Permalink to &quot;先做三件事&quot;">​</a></h2><ol><li><strong>升级客户端</strong>。平台页面改版导致的问题（消息读不到、发不出）通常已经在新版本修复。</li><li><strong>重启客户端</strong>。关掉重开，让平台窗口重新加载。</li><li><strong>确认平台账号状态</strong>。账号是否在别处被登出、平台是否要求重新验证。</li></ol><p>大部分「AI 突然不回了」的情况到这里就解决了。</p><h2 id="还没解决-生成错误报告" tabindex="-1">还没解决：生成错误报告 <a class="header-anchor" href="#还没解决-生成错误报告" aria-label="Permalink to &quot;还没解决：生成错误报告&quot;">​</a></h2><ol><li>打开客户端菜单里的「错误报告」。</li><li>客户端自动打包日志生成 ZIP，文件管理器会自动打开并选中文件。</li><li>把 ZIP 发到微信服务群（入口在客户端「联系我们」里），描述清楚：<strong>什么平台、什么时间、发生了什么、预期是什么</strong>。</li></ol><p>报告同时会上报服务端并生成报告 ID，支持人员可以直接检索。详见<a href="/aicare-docs/client/report">错误报告</a>。</p><h2 id="接待类问题去哪看" tabindex="-1">接待类问题去哪看 <a class="header-anchor" href="#接待类问题去哪看" aria-label="Permalink to &quot;接待类问题去哪看&quot;">​</a></h2><ul><li><strong>AI 回复内容不对</strong>：不算故障，按<a href="/aicare-docs/faq/accuracy">回答不准怎么办</a>排查配置。</li><li><strong>转人工失败</strong>：看<a href="/aicare-docs/solution/transfer">转人工设置</a>的排查建议，以及工作台「数据分析」里的转接成功率。</li><li><strong>接待异常记录</strong>：工作台「异常记录」标签页汇总了需要跟进的接待问题。</li></ul><h2 id="反馈时的隐私说明" tabindex="-1">反馈时的隐私说明 <a class="header-anchor" href="#反馈时的隐私说明" aria-label="Permalink to &quot;反馈时的隐私说明&quot;">​</a></h2><ul><li>自动上报只包含报告 ID 和必要摘要。</li><li>页面截图和 HTML 快照默认只保存在你的电脑上，仅在你主动上报错误时随日志包上传。</li><li>可以在「设置 → 错误上报」里关闭详细材料的本地保存，见<a href="/aicare-docs/client/report#错误上报设置">错误报告</a>。</li></ul><h2 id="紧急情况" tabindex="-1">紧急情况 <a class="header-anchor" href="#紧急情况" aria-label="Permalink to &quot;紧急情况&quot;">​</a></h2><p>接待完全中断且影响生意时，直接在微信服务群里说明「接待中断」，并附上错误报告 ZIP。这类问题会优先处理。</p>',14)])])}const u=r(l,[["render",i]]);export{f as __pageData,u as default};
